// ---------------------------------------------------------------------------
// Golden Set Evaluator
// ---------------------------------------------------------------------------
//
// Scores pipeline results against golden expectations. Returns a structured
// report that can be serialised to JSON for nightly CI artifacts.

import type { Finding } from '../../src/types/index.js';
import type { ScenarioExpectation } from './expectations.js';

export interface EvalDetail {
  check: string;
  pass: boolean;
  detail: string;
}

export interface ScenarioEvalResult {
  scenario: string;
  pass: boolean;
  score: number;
  checks: EvalDetail[];
}

export interface EvalReport {
  timestamp: string;
  scenarios: Record<string, ScenarioEvalResult>;
  overallPass: boolean;
  overallScore: number;
}

function allFindingsText(findings: Finding[]): string {
  return findings
    .map((f) => [
      f.title,
      f.reasoningSummary,
      ...f.evidence.map((e) => `${e.path} ${e.note}`),
    ].join(' '))
    .join(' ');
}

export function evaluateScenario(
  scenarioName: string,
  expectation: ScenarioExpectation,
  findings: Finding[],
): ScenarioEvalResult {
  const checks: EvalDetail[] = [];
  const top = findings[0];

  // 1. Minimum findings count
  checks.push({
    check: 'minFindings',
    pass: findings.length >= expectation.minFindings,
    detail: `Expected >= ${expectation.minFindings}, got ${findings.length}`,
  });

  // 2. Top finding title matches
  const topTitleMatch =
    top !== undefined &&
    expectation.topFindingMustMatch.some((re) => re.test(top.title));
  checks.push({
    check: 'topFindingTitle',
    pass: topTitleMatch,
    detail: top
      ? `Top finding: "${top.title}"`
      : 'No findings produced',
  });

  // 3. Top finding severity
  const topSeverityMatch =
    top !== undefined &&
    expectation.topFindingSeverity.includes(top.severity);
  checks.push({
    check: 'topFindingSeverity',
    pass: topSeverityMatch,
    detail: top
      ? `Got "${top.severity}", expected one of [${expectation.topFindingSeverity.join(', ')}]`
      : 'No findings',
  });

  // 4. Top finding confidence
  const topConfMatch =
    top !== undefined &&
    top.confidence >= expectation.topFindingMinConfidence;
  checks.push({
    check: 'topFindingConfidence',
    pass: topConfMatch,
    detail: top
      ? `Got ${(top.confidence * 100).toFixed(0)}%, min ${(expectation.topFindingMinConfidence * 100).toFixed(0)}%`
      : 'No findings',
  });

  // 5. Evidence citation coverage
  const allPaths = findings.flatMap((f) => f.evidence.map((e) => e.path));
  for (const pattern of expectation.mustCiteEvidence) {
    const cited = allPaths.some((p) => pattern.test(p));
    checks.push({
      check: `mustCiteEvidence: ${pattern.source}`,
      pass: cited,
      detail: cited ? 'Found matching evidence path' : `No evidence path matches /${pattern.source}/`,
    });
  }

  // 6. No hallucinations
  const fullText = allFindingsText(findings);
  for (const pattern of expectation.mustNotHallucinate) {
    const found = pattern.test(fullText);
    checks.push({
      check: `mustNotHallucinate: ${pattern.source}`,
      pass: !found,
      detail: found
        ? `HALLUCINATION DETECTED: /${pattern.source}/ found in findings text`
        : 'Clean — pattern not found',
    });
  }

  // 7. Root cause match
  const rootCauseText = top?.reasoningSummary ?? '';
  const rootCauseMatch = expectation.rootCauseMustMatch.some((re) =>
    re.test(rootCauseText),
  );
  checks.push({
    check: 'rootCauseMatch',
    pass: rootCauseMatch,
    detail: rootCauseMatch
      ? 'Root cause reasoning matches expected pattern'
      : `Root cause "${rootCauseText.slice(0, 100)}" did not match any expected pattern`,
  });

  // 8. Required identifiers
  for (const id of expectation.mustMentionIdentifiers) {
    const mentioned = fullText.toLowerCase().includes(id.toLowerCase());
    checks.push({
      check: `mustMention: ${id}`,
      pass: mentioned,
      detail: mentioned ? `Found "${id}"` : `"${id}" not found in any finding`,
    });
  }

  const passCount = checks.filter((c) => c.pass).length;
  const score = checks.length > 0 ? passCount / checks.length : 0;

  return {
    scenario: scenarioName,
    pass: checks.every((c) => c.pass),
    score,
    checks,
  };
}

export function buildEvalReport(
  results: Record<string, ScenarioEvalResult>,
): EvalReport {
  const scenarios = results;
  const allResults = Object.values(scenarios);
  const overallPass = allResults.every((r) => r.pass);
  const overallScore =
    allResults.length > 0
      ? allResults.reduce((sum, r) => sum + r.score, 0) / allResults.length
      : 0;

  return {
    timestamp: new Date().toISOString(),
    scenarios,
    overallPass,
    overallScore,
  };
}

// ---------------------------------------------------------------------------
// Golden Set Expectations
// ---------------------------------------------------------------------------
//
// Defines structural expectations for each scenario. These are NOT about
// exact LLM wording — they verify that the correct root cause appears, that
// evidence is cited from the right artifacts, and that no hallucinations
// appear.

import type { FindingSeverity } from '../../src/types/index.js';

export interface ScenarioExpectation {
  /** Human-readable scenario name. */
  name: string;
  /** Minimum number of findings the pipeline should produce. */
  minFindings: number;
  /** Top finding title must match one of these patterns. */
  topFindingMustMatch: RegExp[];
  /** Acceptable severities for the top finding. */
  topFindingSeverity: FindingSeverity[];
  /** Minimum confidence for the top finding. */
  topFindingMinConfidence: number;
  /**
   * Evidence paths across all findings must include at least one match
   * per pattern.
   */
  mustCiteEvidence: RegExp[];
  /**
   * No finding title or reasoning should match these patterns.
   * Catches hallucinations of wrong failure modes.
   */
  mustNotHallucinate: RegExp[];
  /**
   * Root cause (reasoning of top finding) must match at least one pattern.
   */
  rootCauseMustMatch: RegExp[];
  /**
   * Key identifiers that must appear somewhere in findings (titles,
   * reasoning, evidence notes).
   */
  mustMentionIdentifiers: string[];
}

export const GOLDEN_EXPECTATIONS: Record<string, ScenarioExpectation> = {
  'bad-image-tag': {
    name: 'Bad Image Tag (ImagePullBackOff)',
    minFindings: 1,
    topFindingMustMatch: [
      /image.*pull/i,
      /ImagePullBackOff/i,
      /ErrImagePull/i,
      /image.*tag/i,
    ],
    topFindingSeverity: ['critical'],
    // Hypothesis evidence for image-pull-failure uses events + pod-status only
    // (no log evidence in collector), giving 0.74 confidence.  Step 1 correctly
    // routes the log finding through hypothesis dedup (Pod-based components),
    // so the hypothesis becomes the top finding.  Step 5 will further tune this.
    topFindingMinConfidence: 0.74,
    mustCiteEvidence: [
      /pods/i,
      /events/i,
    ],
    mustNotHallucinate: [
      /^CrashLoopBackOff$/i, // wrong failure mode (exact match)
      /missing.*secret/i,     // wrong failure mode
    ],
    rootCauseMustMatch: [
      /image/i,
      /v999\.99\.99|pull|tag|registry/i,
    ],
    mustMentionIdentifiers: ['app-pod', 'myapp:v999.99.99'],
  },

  'missing-secret-crashloop': {
    name: 'Missing Secret CrashLoop',
    minFindings: 1,
    topFindingMustMatch: [
      /CrashLoopBackOff/i,
      /missing.*secret/i,
      /app-credentials/i,
      // New hypothesis rootCause format (title is now just the rootCause string)
      /kubernetes secret.*absent|required.*kubernetes secret|secret.*absent|secret.*fail/i,
    ],
    topFindingSeverity: ['critical'],
    topFindingMinConfidence: 0.85,
    mustCiteEvidence: [
      /pods/i,
      /events/i,
    ],
    mustNotHallucinate: [
      /ImagePullBackOff/i,
    ],
    rootCauseMustMatch: [
      /secret|app-credentials|CrashLoop|FailedMount/i,
    ],
    mustMentionIdentifiers: ['app-pod', 'app-credentials'],
  },

  'ghost-service': {
    name: 'Ghost Service (Cross-Namespace DNS Failure)',
    minFindings: 2,
    topFindingMustMatch: [
      /CrashLoopBackOff/i,
      /dns/i,
      /api-service\.staging/i,
      /no such host/i,
    ],
    // In heuristic mode the CrashLoop symptom currently sorts above the DNS
    // hypothesis. If ranking changes later, the namespace-mismatch DNS finding
    // is still acceptable as the top finding for this scenario.
    topFindingSeverity: ['critical', 'high'],
    topFindingMinConfidence: 0.8,
    mustCiteEvidence: [
      /pods/i,
      /events/i,
      /services/i,
      /staging/i,
    ],
    mustNotHallucinate: [
      /ImagePullBackOff/i,
      /persistentvolumeclaim|storageclass/i,
      /OOMKilled/i,
    ],
    rootCauseMustMatch: [
      /crashloop|backoff|restart/i,
      /dns|no such host|api-service\.staging|namespace/i,
