import { describe, it } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { createTestBundle, getFixturePath } from '../../helpers/create-test-bundle.js';
import { extractBundle, profileBundle } from '../../../src/ingestion/index.js';
import {
  identifyLogFiles,
  mergeAnalyzerResults,
  parseAnalyzerFile,
  parseEventFile,
  parseHelmReleaseFile,
  parseLogFile,
  parseResourceFile,
  sortEventsByTime,
} from '../../../src/parsers/index.js';
import { buildChunkIndex, LexicalSearchIndex } from '../../../src/ai/index.js';
import { asResourceRelationshipGraph, buildDiagnosticGraph, buildWorkloadGroups, addTemporalCorrelationEdges, addTemporalSequenceEdges } from '../../../src/graph/index.js';
import { investigateWithAI } from '../../../src/investigators/ai-investigator.js';
import { generateSeeds } from '../../../src/investigators/seed-generator.js';

async function buildContext(scenario: string) {
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), `sbi-prompt-${scenario}-`));
  const bundlePath = await createTestBundle(getFixturePath(scenario), path.join(tmpDir, `${scenario}.tar.gz`));
  const manifest = await extractBundle(bundlePath);
  const profile = await profileBundle(manifest);
  const analyzerFiles = profile.manifest.files.filter((f) => f.category === 'analyzer');
  const analyzerBatches = await Promise.all(analyzerFiles.map((f) => parseAnalyzerFile(f.absolutePath)));
  const analyzerResults = mergeAnalyzerResults(analyzerBatches);
  const resourceFiles = profile.manifest.files.filter((f) => f.category === 'kubernetes-resource');
  const resourceBatches = await Promise.all(resourceFiles.map((f) => parseResourceFile(f.absolutePath)));
  const resources = resourceBatches.flat();
  const eventFiles = profile.manifest.files.filter((f) => f.category === 'event');
  const eventBatches = await Promise.all(eventFiles.map((f) => parseEventFile(f.absolutePath)));
  const events = sortEventsByTime(eventBatches.flat());
  const logEntries = identifyLogFiles(profile.manifest);
  const logs = await Promise.all(logEntries.map((f) => parseLogFile(f.absolutePath)));
  const helmFiles = profile.manifest.files.filter((f) => f.category === 'helm-release');
  const helmBatches = await Promise.all(helmFiles.map((f) => parseHelmReleaseFile(f.absolutePath)));
  const helmReleases = helmBatches.flat();
  const resourceSourceFiles = new Map();
  for (let i = 0; i < resourceFiles.length; i++) {
    const file = resourceFiles[i]!;
    const batch = resourceBatches[i] ?? [];
    for (const resource of batch) resourceSourceFiles.set(resource, file.relativePath);
  }
  const context = { analyzerResults, resources, events, logs, profile, resourceSourceFiles, helmReleases };
  const chunks = buildChunkIndex(context);
  const diagnosticGraph = buildDiagnosticGraph(resources, events);
  buildWorkloadGroups(diagnosticGraph);
  addTemporalCorrelationEdges(diagnosticGraph, chunks.filter((c) => c.artifactCategory === 'log'), events);
  addTemporalSequenceEdges(diagnosticGraph, events);
  const lexicalIndex = new LexicalSearchIndex();
  lexicalIndex.build(chunks);
  return { tmpDir, context, chunks, lexicalIndex, resourceGraph: asResourceRelationshipGraph(diagnosticGraph), diagnosticGraph };
}

describe('scratch ai prompt paths', () => {
  it('prints prompts for bad-image-tag and missing-secret-crashloop', async () => {
    for (const scenario of ['bad-image-tag', 'missing-secret-crashloop']) {
      const built = await buildContext(scenario);
      const seeds = generateSeeds(built.context);
      const prompts: Array<{ seedId: string; user: string }> = [];
      let currentSeedId = 'unknown';
      try {
        await investigateWithAI(built.context, seeds, {
          llmClient: {
            setSeedContext(seedId: string) { currentSeedId = seedId; },
            clearSeedContext() { currentSeedId = 'unknown'; },
            async investigateSeed(_system: string, user: string) {
              prompts.push({ seedId: currentSeedId, user });
              return { findings: [] };
            },
            async generateText() { return ''; },
          },
          chunkIndex: built.chunks,
          resourceGraph: built.resourceGraph,
          diagnosticGraph: built.diagnosticGraph,
          lexicalIndex: built.lexicalIndex,
        });
        console.log(`SCENARIO=${scenario}`);
        console.log(JSON.stringify(prompts.map((p) => ({ seedId: p.seedId, paths: [...p.user.matchAll(/Path: (.+)$/gm)].map((m) => m[1]) })), null, 2));
      } finally {
        fs.rmSync(built.tmpDir, { recursive: true, force: true });
      }
    }
  });
});

